<script setup>
import { computed } from 'vue';
import { fdate,lc,num,stripHtml } from '../../lib/client-info';
import { useClientMedical } from '../../composables/useClientMedical';
import ClientSections from './ClientSections.vue';
const props=defineProps({bundle:Object,metrics:Object});
const {data,loading,error,load}=useClientMedical(props.bundle);
const weights=computed(()=>props.bundle.sessions.filter(row=>num(row.before_weight)>0).sort((a,b)=>String(a.start_date).localeCompare(String(b.start_date))));
const start=computed(()=>weights.value.length?num(weights.value[0].before_weight):0);
const latest=computed(()=>weights.value.length?(num(weights.value.at(-1).after_weight)||num(weights.value.at(-1).before_weight)):0);
const change=computed(()=>Math.round((latest.value-start.value)*10)/10);
const spark=computed(()=>{const values=weights.value.slice(-24).map(row=>num(row.after_weight)||num(row.before_weight));if(values.length<2)return'';const min=Math.min(...values),range=Math.max(.1,Math.max(...values)-min);return values.map((value,index)=>(index/(values.length-1)*300).toFixed(1)+','+(52-(value-min)/range*44).toFixed(1)).join(' ');});
const sections=computed(()=>[
 {id:'flag',icon:props.metrics.med.isMedical?'🩺':'🌿',title:props.metrics.med.isMedical?'Medical client':'Non-medical client',tone:props.metrics.med.flagged.length?'neg':props.metrics.med.isMedical?'warn':'ok',badge:props.metrics.med.flagged.length?props.metrics.med.flagged.length+' major':'',wide:true},
 {id:'history',icon:'📋',title:'Recorded medical details',badge:props.metrics.med.issues.length},
 {id:'weight',icon:'⚖️',title:'Weight journey',badge:weights.value.length?(change.value>0?'+':'')+change.value+' kg':'',tone:change.value<0?'ok':change.value>0?'neg':'mute'},
 {id:'plans',icon:'🏷️',title:'Health status by plan',badge:props.bundle.plans.length},
 {id:'vitals',icon:'❤️',title:'Vital signs',badge:data.value?.vitals.length??'—'},
 {id:'encounters',icon:'👨‍⚕️',title:'Doctor consultations',badge:data.value?.enc.length??'—'},
]);
</script>
<template><div><p v-if="loading" role="status" class="c3-note">Loading vital signs and consultations…</p><p v-if="error" role="alert" class="c3-alert tone-neg">Medical records unavailable: {{ error }} <button type="button" class="c3-btn c3-btn-sm" @click="load">Retry</button></p><ClientSections name="medical" :sections="sections"><template #flag><div v-if="metrics.med.flagged.length" class="c3-alerts"><div v-for="row in metrics.med.flagged" :key="row.key" class="c3-alert tone-neg"><span>⚠️</span><p><b>{{ row.label }}:</b> {{ row.text }}</p></div></div><div v-else class="c3-alert" :class="metrics.med.isMedical?'tone-warn':'tone-ok'"><span>{{ metrics.med.isMedical?'🩺':'🌿' }}</span><p>{{ metrics.med.isMedical?'Marked medical on a therapy plan. Check history before every procedure.':'No major medical conditions recorded.' }}</p></div></template><template #history><div v-if="metrics.med.issues.length" class="c3-grid c3-g2"><div v-for="row in metrics.med.issues" :key="row.key" class="c3-kv" :class="{'is-neg':metrics.med.flagged.includes(row)}"><small>{{ row.label }}</small><b>{{ row.text }}</b></div></div><div v-else class="c3-empty-sm">No allergies, medication or history filled on the Patient record.</div></template><template #weight><template v-if="weights.length"><div class="c3-grid c3-g3"><div class="c3-kv"><small>Starting weight</small><b>{{ start }} kg</b></div><div class="c3-kv"><small>Latest weight</small><b>{{ latest }} kg</b></div><div class="c3-kv"><small>Change</small><b :class="change<0?'tone-ok':change>0?'tone-neg':''">{{ change<0?'▼':change>0?'▲':'=' }} {{ Math.abs(change) }} kg</b></div></div><svg v-if="spark" class="c3-spark" viewBox="0 0 300 56" preserveAspectRatio="none" role="img" aria-label="Weight trend"><polyline :points="spark" /></svg></template><div v-else class="c3-empty-sm">No weights captured in sessions.</div></template><template #plans><div v-if="bundle.plans.length" class="c3-chips"><span v-for="row in bundle.plans" :key="row.name" class="c3-chip" :class="{'tone-neg':lc(row.custom_health_status)==='medical'}">{{ lc(row.custom_health_status)==='medical'?'🩺':'🌿' }} {{ row.name }}: {{ row.custom_health_status||'—' }}</span></div><div v-else class="c3-empty-sm">No plans.</div></template><template #vitals><div v-if="data?.vitals.length" class="c3-table-wrap"><table class="c3-mini-table"><thead><tr><th>Date</th><th>Weight</th><th>BMI</th><th>BP</th><th>Pulse</th><th>Note</th></tr></thead><tbody><tr v-for="row in data.vitals" :key="row.name"><td>{{ fdate(row.signs_date) }}</td><td>{{ row.weight||'—' }}</td><td>{{ row.bmi||'—' }}</td><td>{{ row.bp||'—' }}</td><td>{{ row.pulse||'—' }}</td><td>{{ row.nutrition_note||'' }}</td></tr></tbody></table></div><div v-else class="c3-empty-sm">{{ loading?'Loading vital signs…':error?'Vital signs unavailable.':'No vital signs recorded.' }}</div></template><template #encounters><div v-if="data?.enc.length" class="c3-cards c3-c2"><article v-for="row in data.enc" :key="row.name" class="c3-card"><header class="c3-card-h"><div><b>{{ fdate(row.encounter_date) }}</b><small>{{ row.practitioner_name||'' }} {{ row.medical_department||'' }}</small></div></header><p v-if="row.encounter_comment" class="c3-fu-remark">{{ stripHtml(row.encounter_comment) }}</p></article></div><div v-else class="c3-empty-sm">{{ loading?'Loading consultations…':error?'Consultations unavailable.':'No consultations recorded.' }}</div></template></ClientSections></div></template>
